# Primera clasificación de los materiales que ya hay, según su tipo.
# Es un punto de partida: Oficina puede cambiar la clase de cualquier material desde la web.
TIPOS_SOPORTE = ['Soportes y fijaciones', 'Estructuras solares', 'Soportes']
TIPOS_ACCESORIO = ['Accesorios', 'Accesorios hidráulicos', 'Aislamientos', 'Filtros y separadores de lodos',
                   'Instrumentos de medida', 'Llenado y vaciado', 'Líquidos y tratamientos', 'Válvulas',
                   'Pantallas y mandos', 'Repuestos', 'Protecciones eléctricas', 'Enchufes', 'Mecanismos',
                   'Material vario', 'Desagües y saneamiento', 'Medidores de energía', 'Pasarelas y comunicación']


def entregas_a_citas(apps, schema_editor):
    # Cada fecha de entrega que había pasa a ser una cita, para no perderla
    Proyecto = apps.get_model('gestion', 'Proyecto')
    Cita = apps.get_model('gestion', 'Cita')
    for proyecto in Proyecto.objects.exclude(fecha_entrega=None):
        Cita.objects.create(proyecto=proyecto, fecha=proyecto.fecha_entrega, motivo='Entrega')


def clasificar_materiales(apps, schema_editor):
    Material = apps.get_model('gestion', 'Material')
    # Mano de obra y servicios no son material: se quedan sin clase
    Material.objects.filter(categoria='MOB').update(clase='')
    Material.objects.exclude(categoria='MOB').filter(tipo__nombre__in=TIPOS_SOPORTE).update(clase='SOP')
    Material.objects.exclude(categoria='MOB').filter(tipo__nombre__in=TIPOS_ACCESORIO).update(clase='ACC')


def crear_horas(apps, schema_editor):
    # Dos tipos de hora nuevos junto a Oficial y Pareja. Precio provisional: Oficina lo cambia en Materiales
    Categoria = apps.get_model('gestion', 'Categoria')
    Tipo = apps.get_model('gestion', 'Tipo')
    Material = apps.get_model('gestion', 'Material')
    if not Categoria.objects.filter(pk='MOB').exists():
        return
    horas, _ = Tipo.objects.get_or_create(nombre='Horas', categoria_id='MOB')
    for nombre, precio in [('Hora Peón', '25.00'), ('Hora Subcontrata', '30.00')]:
        if not Material.objects.filter(nombre=nombre).exists():
            Material.objects.create(nombre=nombre, categoria_id='MOB', tipo=horas, unidad='H', precio=precio, clase='')



